import os, sys
HERE = os.path.dirname(os.path.abspath(__file__)); HERE = HERE[:-5] if HERE.endswith(("/W_zh", "/W_en")) else HERE; SK = os.path.abspath(os.path.join(HERE, "..", ".."))
for p in ("view-from-text-v3/tools", "view-from-text-v3/examples", "view-from-text-v2/tools", "view-from-text-v2/examples"): sys.path.insert(0, os.path.join(SK, p))
sys.path.insert(0, HERE)
import kp16_pages as KP
from htmlkit import native
JD = os.path.join(HERE, "out")
UNIT_ZH, UNIT_EN = "RBF 網路", "The RBF network"
TITLE_ZH = "圖型識別 第四章 KP16：RBF 網路（大三）"; TITLE_EN = "Pattern Recognition, Chapter 4, KP16: the RBF network (undergraduate)"
NOTE_ZH = "教材程度：大學三年級（undergrad）。依講義 lec05-kp16 以 view-from-text-v3 製作：先規劃頁面，每頁以一張原生資訊圖（HTML 設計後轉成原生節點）為主，名詞在同一頁圖內定義。主線 7 頁，另有 2 頁延伸（不計時）；講義 §3、§4 合併為第 3 頁，延伸的練習與解題示範合併為一頁。"
NOTE_EN = "Level: undergraduate (year 3). Made from the lecture lec05-kp16 with view-from-text-v3: pages were planned first and each page is mainly one native infographic (designed in HTML and converted to native nodes), with the terms defined on the same page. 7 main pages plus 2 extension pages (not timed); sections 3 and 4 of the lecture are merged into page 3, and the extension exercises and worked answers share one page."
def fig(n, alt_zh, alt_en): return lambda: native(f"kp16_p{n}", f"lec05-kp16-p{n}", KP.W, KP.H, JD, alt_en if os.environ.get("KP_LANG") == "en" else alt_zh)
NXT = {1: ("局部與全域", "local versus global response"), 2: ("XOR 兩個中心", "XOR with two centres"), 3: ("固定中心", "fixed centres"), 4: ("分群選中心", "choosing centres by clustering"), 5: ("局部的代價", "the price of locality"), 6: ("MLP 對 RBF", "MLP versus RBF"), 7: ("中心的選法（延伸）", "ways to choose centres (extension)"), 8: ("練習（延伸）", "the exercises (extension)")}
PRV = {2: ("高斯節點", "the Gaussian node"), 3: ("局部與全域", "local versus global response"), 4: ("XOR 兩個中心", "XOR with two centres"), 5: ("固定中心", "fixed centres"), 6: ("分群選中心", "clustering"), 7: ("局部的代價", "the price of locality"), 8: ("MLP 對 RBF", "MLP versus RBF"), 9: ("中心的選法", "ways to choose centres")}
P = []
def add(n, lab, title, bridge, notes, alt):
    zh, en = notes
    if n in PRV: zh = f"承接上一頁的「{PRV[n][0]}」。" + zh; en = f"Following the previous page on {PRV[n][1]}. " + en
    if n in NXT: zh += f"接下來的下一頁是「{NXT[n][0]}」。"; en += f" Next, the next page covers {NXT[n][1]}."
    if n == 9: zh += "到這裡這個單元就結束了；之後請接著讀下一單元。"; en += " That ends this unit; next, move on to the next unit."
    P.append(dict(lab=lab, title=title, bridge=bridge, notes=(zh, en), layout="freeform", spec=fig(n, *alt)))
add(1, ("高斯節點", "Gaussian node"), ("RBF 網路：每個節點只在自己的中心附近有反應", "The RBF network: each node reacts only near its own centre"),
    ("KP15 的乘積項對整個空間都有反應。能不能換成只對附近資料有反應的新座標？", "The product terms of KP15 react over the whole space. Can we use new coordinates that react only to nearby data?"),
    ("這是 KP16 的第一頁。先備三件事：廣義線性分類器（KP13），先用固定函數把 x 換成新座標，再學一個對權重線性的分類器；距離與範數，例如 x 等於 0.5,0.5、c 等於 0,0 時，距離平方是 0.25 加 0.25 等於 0.5；最小二乘（KP13）。KP15 的乘積項對整個空間都有反應，這一課問：能不能換成只對附近資料有反應的新座標？答案是徑向基函數，也就是以到中心 c i 的距離為引數的函數，最常用高斯形。RBF 網路 g of x 等於 w0 加上 i 從 1 到 k 的 w i 乘 exp 負 x 減 c i 的範數平方除以 2 sigma i 平方，是一層高斯隱藏節點加線性輸出。圖上方：一個 sigmoid 節點的回應在整條線的一側都是高的，是全域反應；下方：三個高斯各自只在自己的中心附近有回應，離開就降到 0，是局部反應。它與 Parzen 估計血緣很近，但 Parzen 每個訓練點一個核，k 等於 N，這裡 k 遠小於 N。",
     "This is the first page of KP16. Prerequisites: generalized linear classifiers (KP13), which first change x into new coordinates with fixed functions and then learn a classifier linear in the weights; distance and norm, for example x equal to 0.5, 0.5 and c equal to 0, 0 give a squared distance of 0.25 plus 0.25, which is 0.5; and least squares (KP13). The product terms of KP15 react over the whole space, and this lesson asks whether we can use new coordinates that react only to nearby data. The answer is the radial basis function, a function of the distance to a centre c i, most often Gaussian. The RBF network g of x equals w0 plus the sum over i from 1 to k of w i times exp of minus the squared norm of x minus c i over 2 sigma i squared: one layer of Gaussian hidden nodes plus a linear output. In the upper plot a sigmoid node is high on a whole side of the line, a global response; in the lower plot three Gaussians each respond only near their own centre and fall to 0 away from it, a local response. It is close to a Parzen estimate, but Parzen has one kernel per training point, k equal to N, while here k is much smaller than N."),
    ("RBF network g(x)=w0+sum w_i exp(-|x-c_i|^2/(2 sigma^2)); upper plot: one sigmoid node responds on a whole side (global); lower plot: three Gaussian nodes at -2.4, 0 and 2.4 each respond only near their centre (local); Parzen has k=N, RBF k much smaller than N.",) * 2)
add(2, ("局部與全域", "Local versus global"), ("sigmoid 的等值線是直線，RBF 的是圓：全域對局部反應", "A sigmoid has straight iso-lines, an RBF circles: global versus local response"),
    ("高斯節點只在自己的中心附近有反應，離開就降到 0。這在二維平面上和 sigmoid 差在哪？", "A Gaussian node reacts only near its own centre and falls to 0 away from it. In the plane, how does that differ from a sigmoid?"),
    ("上一頁看到高斯節點只在自己的中心附近有反應，這一頁問：在二維平面上，局部與全域的差別長什麼樣？全域反應是沿整個超平面回應，sigmoid 節點的等值集合是超平面，二維是一組平行直線。局部反應是節點只在中心附近回應，離開就趨近 0，RBF 節點的等值集合是超球面，二維是以中心為圓心的同心圓。右邊的例子取 2 sigma 平方等於 1，距中心 d 等於 0、1、2、3 時，高斯回應 e 的負 d 平方次方是 1、0.368、0.0183、0.000123；離中心三個單位，回應只剩萬分之一（程式計算）。",
     "The previous page showed a Gaussian node reacting only near its own centre; this page asks what local versus global looks like in the plane. A global response runs along a whole hyperplane: the iso-set of a sigmoid node is a hyperplane, a family of parallel lines in two dimensions. A local response means the node answers only near its centre and goes to 0 away from it: the iso-set of an RBF node is a hypersphere, concentric circles around the centre in two dimensions. In the example on the right 2 sigma squared is 1, and at distances d equal to 0, 1, 2, 3 from the centre the Gaussian response e to the minus d squared is 1, 0.368, 0.0183, 0.000123; three units away the response is only one in ten thousand (program computed)."),
    ("Left: sigmoid iso-lines are parallel straight lines (global response); middle: RBF iso-lines are concentric circles (local response); right: Gaussian response e^(-d^2) at d=0,1,2,3 is 1, 0.368, 0.0183, 0.000123.",) * 2)
add(3, ("XOR 兩個中心", "XOR with two centres"), ("XOR 只要兩個中心：(1,0) 與 (0,1) 被摺到同一點，原空間是封閉曲線", "XOR needs only two centres: (1,0) and (0,1) fold onto one point and the original space gets a closed curve"),
    ("RBF 的等值線是同心圓，離中心遠就趨近 0。這樣的節點，兩個就能解 XOR 嗎？直線回到原空間又是什麼？", "The iso-lines of an RBF are concentric circles and the response goes to 0 far from the centre. Can two such nodes solve XOR, and what is the line in the original space?"),
    ("上一頁看到 RBF 的等值線是同心圓。這一頁用 XOR 來問：兩個這樣的節點就夠了嗎？設定：k 等於 2，c1 等於 1,1、c2 等於 0,0，y i 等於 exp 負 x 減 c i 的距離平方，也就是 2 sigma 平方等於 1。逐點算：0,0 到 c1 的距離平方是 2、到 c2 是 0，y 等於 0.135 與 1，g 等於 y1 加 y2 減 1 是正 0.135；1,1 同理也是正 0.135；1,0 與 0,1 到兩個中心的距離平方都是 1，y 都是 0.368 與 0.368，g 是負 0.264。1,0 與 0,1 都被映射到同一點，也就是被摺疊起來，一條直線 y1 加 y2 等於 1 就把兩類分開。回到原空間：g of x 等於 0 是圍住兩個中心的封閉曲線，0,0 與 1,1 在內，1,0 與 0,1 在外；離所有中心都很遠時兩個指數項都趨近 0，所以 g 趨近負 1，遠處一律歸曲線外那一類，這是局部反應的特性。",
     "The previous page showed that the iso-lines of an RBF are concentric circles. This page asks, with XOR, whether two such nodes are enough. Setup: k equal to 2, c1 equal to 1, 1, c2 equal to 0, 0, and y i equal to exp of minus the squared distance to c i, that is 2 sigma squared equal to 1. Point by point: the point 0, 0 has squared distance 2 to c1 and 0 to c2, so y is 0.135 and 1 and g equal to y1 plus y2 minus 1 is plus 0.135; 1, 1 is the same, also plus 0.135; the points 1, 0 and 0, 1 have squared distance 1 to both centres, so y is 0.368 and 0.368 and g is minus 0.264. The points 1, 0 and 0, 1 are mapped to the same point, that is folded together, and the single line y1 plus y2 equal to 1 separates the two classes. Back in the original space, g of x equal to 0 is a closed curve around the two centres, with 0, 0 and 1, 1 inside and 1, 0 and 0, 1 outside; far from every centre both exponentials go to 0 so g goes to minus 1, and far points all fall in the outside class, a feature of local response."),
    ("Left, original plane: closed curve g(x)=0 around centres c1=(1,1), c2=(0,0); (0,0),(1,1) inside; (1,0),(0,1) outside. Middle, feature plane: line y1+y2=1; (1,0) and (0,1) fold onto (0.368,0.368). Right table: g = +0.135, +0.135, -0.264, -0.264.",) * 2)
add(4, ("固定中心", "Fixed centres"), ("中心從訓練點隨機挑：環形資料 k=16 就 99.5%", "Centres picked at random from the training points: 99.5% on ring data at k = 16"),
    ("XOR 的兩個中心是手選的，兩個中心就圍出封閉曲線。資料多的時候，中心從哪裡來、要幾個？", "The two centres of XOR were chosen by hand and already enclose a closed curve. With many data points, where do the centres come from and how many are needed?"),
    ("上一頁 XOR 的兩個中心是手選的，兩個中心就圍出封閉曲線。資料多的時候，中心從哪裡來？最簡單的是固定中心：從訓練資料隨機挑 k 個點當中心；中心固定後只剩 w 要學，就是 KP13 的線性問題，用最小二乘解。實驗設定是我設計的，可重現：同心環資料，角度均勻，半徑 A 類是 N(1.0, 0.15 平方)、B 類是 N(2.2, 0.2 平方)，各類 100 點共 200 個訓練點，亂數 default_rng(0)；新點各類 500 點共 1000 點，default_rng(1)；2 sigma 平方等於 1；預測取 g 的正負號；每個 k 以種子 0 到 19 各挑一次中心，共 20 次，取新點正確率的平均。k 等於 1、2、4、8、16、32 的新點正確率是 56.0、64.2、76.1、91.5、99.5、99.9 百分比。中心越多，越能圍出內圈；k 等於 16 已接近全對。",
     "On the previous page the two XOR centres were chosen by hand and already enclosed a closed curve. With many data points, where do the centres come from? The simplest answer is fixed centres: pick k training points at random as the centres; with the centres fixed only w is left to learn, which is the linear problem of KP13, solved by least squares. The setup is my own design and reproducible: concentric-ring data with uniform angles, radius N(1.0, 0.15 squared) for class A and N(2.2, 0.2 squared) for class B, 100 points per class and 200 training points in total with random generator default_rng(0); new points 500 per class, 1000 in total, with default_rng(1); 2 sigma squared equal to 1; the prediction is the sign of g; for each k the centres are drawn once per seed 0 to 19, 20 times in all, and the new-point accuracy is averaged. For k equal to 1, 2, 4, 8, 16, 32 the new-point accuracy is 56.0, 64.2, 76.1, 91.5, 99.5, 99.9 percent. More centres enclose the inner ring better; k equal to 16 is already almost all correct."),
    ("Left: concentric ring data (inner class A, outer class B) with 8 randomly chosen centres. Right: new-point accuracy against the number of centres k: 56.0%, 64.2%, 76.1%, 91.5%, 99.5%, 99.9% for k=1,2,4,8,16,32.",) * 2)
add(5, ("分群選中心", "Choosing centres by clustering"), ("分群選中心：兩個月牙 k=8 時 95.0%，比隨機的 93.3% 更穩", "Choosing centres by clustering: 95.0% on two moons at k = 8, steadier than random's 93.3%"),
    ("隨機挑中心，環形資料 k=16 就 99.5%，但每次挑的結果不同。先分群再取群平均，一定比隨機準嗎？", "Fixed centres picked at random reached 99.5% new-point accuracy on the ring data at k = 16, but every draw differs. Does clustering first and taking the group means always beat random?"),
    ("上一頁隨機挑中心，環形資料 k 等於 16 就 99.5%，但每次挑的結果不同。這一頁問：先分群再取群平均，一定比隨機準嗎？分群是這裡用 k-means：先把資料分成 k 群，每群的平均當中心，再用監督式的最小二乘學 w，是非監督加監督的混合。實驗設定是我設計的，可重現：兩個月牙，A 類取上半圓 cos t, sin t、B 類取平移的下半圓 1 減 cos t, 0.5 減 sin t，t 在 0 到 pi 均勻，各加標準差 0.2 的高斯雜訊；各類 60 點共 120 個訓練點，種子 0；新點各類 500 點共 1000 點，種子 1；2 sigma 平方等於 0.6；k-means 50 輪，初始中心也是隨機挑的 k 個點；每個 k 以種子 0 到 19 各做一次，取平均。隨機對 k-means：k 等於 2 是 76.3 對 73.5，4 是 84.4 對 83.1，6 是 90.5 對 92.7，8 是 93.3 對 95.0，12 是 94.9 對 95.2。常見迷思是分群一定比隨機準：k 等於 2、4 時隨機反而略高；k 至少 6 時分群較高，但主要的差別是更穩，k 等於 8 時標準差是 0.004 對 0.018。",
     "On the previous page random centres reached 99.5% on the ring data at k equal to 16, but every draw differs. This page asks whether clustering first and taking the group means always beats random. The clustering here is k-means: first split the data into k groups and use each group mean as a centre, then learn w by supervised least squares, a mix of unsupervised and supervised learning. The setup is my own design and reproducible: two moons, class A on the upper half circle cos t, sin t and class B on the shifted lower half circle 1 minus cos t, 0.5 minus sin t, with t uniform on 0 to pi and Gaussian noise of standard deviation 0.2; 60 points per class and 120 training points in total with seed 0; 500 new points per class, 1000 in total, with seed 1; 2 sigma squared equal to 0.6; k-means runs 50 rounds from randomly chosen initial centres; each k is run once per seed 0 to 19 and averaged. Random against k-means: k equal to 2 gives 76.3 against 73.5, 4 gives 84.4 against 83.1, 6 gives 90.5 against 92.7, 8 gives 93.3 against 95.0, 12 gives 94.9 against 95.2. The common myth is that clustering always beats random: at k equal to 2 and 4 random is slightly higher; from k equal to 6 clustering is higher, but the main difference is that it is steadier, with standard deviation 0.004 against 0.018 at k equal to 8."),
    ("Left: two-moons data with 8 k-means centres. Right: new-point accuracy, random centres versus k-means: k=2: 76.3% vs 73.5%; k=4: 84.4% vs 83.1%; k=6: 90.5% vs 92.7%; k=8: 93.3% vs 95.0% (std 0.018 vs 0.004); k=12: 94.9% vs 95.2%.",) * 2)
add(6, ("局部的代價", "The price of locality"), ("局部的代價是維度：l=10 時 100 個中心只照到 40% 的點", "The price of locality is dimension: at l = 10, 100 centres cover only 40% of the points"),
    ("不論隨機挑還是分群，中心都要填滿資料所在的空間。維度升高時，這件事會怎樣？", "The clustered centres were steadier than random on two moons at k = 8, yet centres must still fill the space where the data live. What happens as the dimension grows?"),
    ("上一頁不論隨機挑還是分群，中心都要填滿資料所在的空間。這一頁問：維度升高時，這件事會怎樣？維度詛咒是維度升高，要填滿空間所需的點或中心數呈指數成長，而資料與中心卻永遠不夠。實驗設定是我設計的，可重現：在單位立方體 0 到 1 的 l 次方裡均勻隨機放 100 個中心，再抽 2000 個測試點；亂數 default_rng(0)，依 l 等於 1、2、5、10、20 順序接續使用；高斯寬度 sigma 等於 0.3，回應是 exp 負 d 平方除以 2 sigma 平方，d 是測試點到最近中心的距離。最近中心距離的中位數：l 等於 2、5、10、20 時是 0.05、0.30、0.67、1.22；回應大於 0.1 的測試點比例是 100%、100%、40%、0%。對照：每軸放 5 個中心的格子，l 等於 2、5、10 要 25、3125、9,765,625 個中心。",
     "On the previous page the centres, whether picked at random or by clustering, had to fill the space where the data live. This page asks what happens as the dimension grows. The curse of dimensionality: as the dimension grows, the number of points or centres needed to fill the space grows exponentially, while data and centres are never enough. The setup is my own design and reproducible: 100 centres are placed uniformly at random in the unit cube 0 to 1 to the power l, and 2000 test points are drawn; random generator default_rng(0), used in sequence for l equal to 1, 2, 5, 10, 20; Gaussian width sigma equal to 0.3 and the response exp of minus d squared over 2 sigma squared, with d the distance from the test point to the nearest centre. Median distance to the nearest centre for l equal to 2, 5, 10, 20: 0.05, 0.30, 0.67, 1.22; the share of test points with response above 0.1 is 100%, 100%, 40%, 0%. For comparison a grid with 5 centres per axis needs 25, 3125 and 9,765,625 centres for l equal to 2, 5, 10."),
    ("Share of test points with response above 0.1 with 100 centres: l=2 100%, l=5 100%, l=10 40%, l=20 0%; median nearest-centre distance 0.05, 0.30, 0.67, 1.22; a 5-per-axis grid needs 25, 3125, 9,765,625 centres for l=2,5,10.",) * 2)
add(7, ("MLP 對 RBF", "MLP versus RBF"), ("MLP 看超平面哪一側，RBF 看離中心多近：全域對局部", "An MLP asks which side of a hyperplane, an RBF how near a centre: global versus local"),
    ("局部的代價是維度：l=10 時 100 個中心只照到 40% 的點。那 RBF 與 MLP 到底怎麼取捨？", "The price of locality is dimension: at l = 10, 100 centres cover only 40% of the points. So how should we choose between an RBF and an MLP?"),
    ("上一頁看到局部的代價是維度：l 等於 10 時 100 個中心只照到 40% 的點。這一頁把 MLP 與 RBF 放在一起比：節點的引數，MLP 是權重與輸入的加權和，RBF 是到中心的距離；等值集合，MLP 是超平面，RBF 是超球面；反應，MLP 是全域，RBF 是局部；學習速度，MLP 較慢，RBF 較快；訓練資料稀疏處的泛化，MLP 較好，RBF 較差；同樣效能所需節點數，MLP 較少，RBF 多很多。比較表依來源。怎麼記：MLP 用在超平面哪一側思考，RBF 用離中心多近思考；局部學得快，但吃維度。",
     "The previous page showed that the price of locality is dimension: at l equal to 10 the 100 centres cover only 40% of the points. This page puts the MLP and the RBF side by side: the argument of a node is a weighted sum for the MLP and the distance to a centre for the RBF; the iso-set is a hyperplane for the MLP and a hypersphere for the RBF; the response is global for the MLP and local for the RBF; learning is slower for the MLP and faster for the RBF; generalization where training data are sparse is better for the MLP and worse for the RBF; and the number of nodes needed for the same performance is smaller for the MLP and much larger for the RBF. The table follows the source. To remember: an MLP thinks about which side of a hyperplane, an RBF about how near a centre; local learns fast but eats dimensions."),
    ("Comparison table MLP versus RBF: node argument sum w_j x_j versus |x-c_i|; hyperplane versus hypersphere; global versus local; slower versus faster; better versus worse generalization where data are sparse; fewer versus many more nodes.",) * 2)
add(8, ("中心的選法", "Ways to choose centres"), ("延伸：中心的六種選法，從隨機挑到支持向量與成長式", "Extension: six ways to choose centres, from random picks to support vectors and growing"),
    ("RBF 看離中心多近，局部學得快，但吃維度，要很多中心。這些中心除了隨機挑與分群，還有哪些選法？", "Global versus local: the RBF learns fast but eats dimensions. Besides random picks and clustering, how else can the centres be chosen?"),
    ("上一頁比較 MLP 與 RBF：RBF 局部學得快，但要很多中心。這一頁是延伸，來源列出中心的六種選法：固定中心，從訓練點隨機挑；訓練中心，w、c、sigma 全用梯度下降，成本高；分群，k-means，群平均當中心；正交最小平方，先給一大堆候選，用前向回歸挑出精簡中心，順便估出 k；支持向量，把 RBF 網路看成核映射，訓練是二次規劃、保證全域最佳，中心個數自動決定；成長式，新樣本若離所有中心都遠、誤差又大，就成為新中心。",
     "The previous page compared the MLP and the RBF: the RBF learns fast locally but needs many centres. This page is an extension, and the source lists six ways to choose centres: fixed centres, picked at random from the training points; trained centres, with w, c and sigma all by gradient descent, which is costly; clustering, k-means, with group means as centres; orthogonal least squares, which starts from many candidates and picks a compact set by forward regression, also estimating k; support vectors, which view the RBF network as a kernel map so that training is a quadratic programme with a global optimum and the number of centres is chosen automatically; and growing, where a new sample far from all centres with a large error becomes a new centre."),
    ("Six ways to choose centres: fixed (random training points), trained (gradient descent on w, c, sigma), clustering (k-means group means), orthogonal least squares (forward regression), support vectors (kernel map, quadratic programme), growing (far and wrong samples become centres).",) * 2)
add(9, ("練習", "Exercises"), ("延伸：兩題練習，映射中間點 (0.5, 0.5) 與遠點 (3, 3)", "Extension: two exercises, mapping the middle point (0.5, 0.5) and the far point (3, 3)"),
    ("中心的六種選法裡，XOR 例子用的是手選的兩個中心。用它來映射兩個新點，會判成哪一類？", "Of the six ways to choose centres, the XOR example used two centres chosen by hand. Mapping two new points with them, which class do they get?"),
    ("上一頁列了中心的六種選法，XOR 例子用的是手選的兩個中心。這一頁用它做練習：c1 等於 1,1、c2 等於 0,0，y i 等於 exp 負 x 減 c i 的距離平方，g 等於 y1 加 y2 減 1，g 大於 0 為 omega 1。題 1：把 0.5,0.5 映射到 y 並判類，到兩個中心的距離平方都是 0.5，y 等於 0.607 與 0.607，g 等於 0.607 加 0.607 減 1 是正 0.213，大於 0，屬 omega 1。題 2：對遠點 3,3，到 c1、c2 的距離平方是 8 與 18，y 等於 0.0003 與 1.5 乘 10 的負 8 次方，g 約為負 1.0，小於 0，屬 omega 2。核對：中間點在兩個中心之間，被圍進曲線內；遠點落到偏置負 1，歸預設那一類。",
     "The previous page listed six ways to choose centres, and the XOR example used two centres chosen by hand. This page uses them for exercises: c1 equal to 1, 1, c2 equal to 0, 0, y i equal to exp of minus the squared distance to c i, g equal to y1 plus y2 minus 1, and g above 0 means omega 1. Q1: map 0.5, 0.5 to y and classify it; the squared distance to both centres is 0.5, y equals 0.607 and 0.607, g equals 0.607 plus 0.607 minus 1, which is plus 0.213, above 0, so class omega 1. Q2: for the far point 3, 3 the squared distances to c1 and c2 are 8 and 18, y equals 0.0003 and 1.5 times 10 to the minus 8, g is about minus 1.0, below 0, so class omega 2. Check: the middle point lies between the two centres and is enclosed by the curve; the far point falls to the bias minus 1 and takes the default class."),
    ("Exercise 1: (0.5,0.5) maps to y=(0.607,0.607), g=+0.213, class omega 1. Exercise 2: (3,3) has squared distances 8 and 18, y=(0.0003, 1.5e-8), g about -1.0, class omega 2.",) * 2)
PAGES = P
